/* Рацион+ — offline-first PWA. No personal data or API keys are bundled into public source. */
(()=>{'use strict';
const KEY='ration_plus_v1';const APIKEY='ration_plus_connection_v1';const $=id=>document.getElementById(id);
const dateNow=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
const shift=(s,n)=>{const d=new Date(s+'T12:00:00');d.setDate(d.getDate()+n);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
const round=x=>Math.round(Number(x)||0);const fixed=x=>Number(Number(x||0).toFixed(1));const num=x=>Number(String(x??'').replace(',','.'));
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,10);
const initialPlan=()=>[
 {id:uid(),name:'Жим ногами в гакке',weight:50,sets:2,reps:'10'},
 {id:uid(),name:'Ягодичный мост в тренажёре',weight:25,sets:2,reps:'12'},
 {id:uid(),name:'Жим от груди в тренажёре',weight:15,sets:2,reps:'12'},
 {id:uid(),name:'Горизонтальная тяга',weight:27.2,sets:2,reps:'12'},
 {id:uid(),name:'Вертикальная тяга широким хватом',weight:27.2,sets:2,reps:'12'},
 {id:uid(),name:'Сгибание ног лёжа',weight:15,sets:2,reps:'12'},
 {id:uid(),name:'Обратная бабочка',weight:18.1,sets:2,reps:'12'},
 {id:uid(),name:'Подъём коленей на перекладине',weight:0,sets:2,reps:'12'}
];
function makeProfile(name='Мой профиль',withPlan=true){return{id:uid(),name,height:null,weight:null,age:null,sex:'male',activity:1.375,goal:'cut',cal:2500,protein:175,fat:75,carbs:280,meals:[],workouts:[],measurements:[],activeWorkout:null,trainingPhase:withPlan?'return':'steady',plan:withPlan?initialPlan():[]}}
const starter=()=>{let p=makeProfile();return{version:1,selectedProfile:p.id,profiles:[p]}};
let db;try{db=JSON.parse(localStorage.getItem(KEY)||'null')}catch{}if(!db||!Array.isArray(db.profiles)||!db.profiles.length)db=starter();
let config;try{config=JSON.parse(localStorage.getItem(APIKEY)||'{}')}catch{config={}}
let day=dateNow(),tab='home',pendingPhotos=[],postPhotoIndex=-1,draftAI=null,busy=false;
const person=()=>db.profiles.find(p=>p.id===db.selectedProfile)||db.profiles[0];
function save(){try{localStorage.setItem(KEY,JSON.stringify(db))}catch{toast('Место для записей закончилось. Сделай резервную копию.')}}
const saveConfig=()=>localStorage.setItem(APIKEY,JSON.stringify(config));
const fmt=n=>round(n).toLocaleString('ru-RU');const measure=n=>Number(n||0).toLocaleString('ru-RU',{maximumFractionDigits:1});
const dateLabel=d=>d===dateNow()?'Сегодня':d===shift(dateNow(),-1)?'Вчера':new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'});
let toastTimer;function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3400)}
function modal(title,html,after){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('modal').classList.add('show');$('modal').setAttribute('aria-hidden','false');if(after)after();}
function close(){if(busy)return;$('modal').classList.remove('show');$('modal').setAttribute('aria-hidden','true');$('modalBody').innerHTML='';pendingPhotos=[];postPhotoIndex=-1;draftAI=null}
const field=(title,id,value='',type='number',extra='')=>`<div class="field"><label for="${id}">${title}</label><input id="${id}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const btn=(id,label,cl='primary')=>`<button type="button" id="${id}" class="btn ${cl}">${label}</button>`;
function empty(s){return `<div class="empty">${s}</div>`}
function sums(d=day){let a={cal:0,p:0,f:0,c:0};person().meals.filter(x=>x.date===d).forEach(x=>{a.cal+=x.cal;a.p+=x.p;a.f+=x.f;a.c+=x.c});return a}
function mealName(x){return esc(x.name||x.mealType||'Приём пищи')}
function dayMealList(d){return person().meals.filter(x=>x.date===d).sort((a,b)=>(b.created||'').localeCompare(a.created||''))}
async function loadThumb(id,img){if(!id)return;try{let data=await getPhoto(id);if(data&&img.isConnected)img.src=data}catch{}}
function mealTile(m){let html=`<div class="item" data-meal="${esc(m.id)}">${m.photoIds?.length?`<img data-photo="${esc(m.photoIds[0])}" alt="Фото еды" loading="lazy">`:""}<div class="itembody"><strong>${mealName(m)}</strong><small>${esc(m.mealType||'Приём пищи')} · ${esc(m.description||'Без описания').slice(0,95)}</small><small>${m.posted?'✓ Опубликовано в Telegram · ':''}${esc(m.source||'Ручной расчёт')}</small></div><div class="numbers"><b>${fmt(m.cal)} ккал</b><small>Б ${measure(m.p)} · Ж ${measure(m.f)} · У ${measure(m.c)}</small></div></div>`;return html}
function attachMealClicks(container){container.querySelectorAll('[data-meal]').forEach(el=>el.onclick=()=>mealDetail(el.dataset.meal));container.querySelectorAll('[data-photo]').forEach(img=>loadThumb(img.dataset.photo,img))}
function renderHome(){let p=person(),t=sums(),remain=p.cal-t.cal,percent=Math.round(t.cal/Math.max(p.cal,1)*100);$('profileSwitch').textContent=p.name+' ▾';$('dateToday').textContent=new Date(day+'T12:00:00').toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'}).toUpperCase();$('dayLabel').textContent=dateLabel(day);$('goalSummary').textContent=({cut:'Снижение жира',maintain:'Поддержание формы',gain:'Набор мышц'})[p.goal]+' · питание и восстановление';$('goalBadge').textContent=({cut:'ДЕФИЦИТ',maintain:'ПОДДЕРЖАНИЕ',gain:'НАБОР'})[p.goal];$('calDonut').style.setProperty('--fill',Math.min(360,Math.max(0,percent*3.6))+'deg');$('calPct').textContent=percent+'%';$('calLeft').textContent=fmt(Math.abs(remain));$('calLeft').style.color=remain<0?'var(--red)':'';$('calEaten').textContent=remain<0?'Превышение '+fmt(-remain)+' ккал':'Съедено '+fmt(t.cal)+' ккал';$('calGoal').textContent=fmt(p.cal);
 for(const [short,sum,target] of [['p',t.p,p.protein],['f',t.f,p.fat],['c',t.c,p.carbs]]){$(short+'Numbers').textContent=measure(sum)+' / '+measure(target)+' г';$(short+'Bar').style.width=Math.max(0,Math.min(100,100*sum/Math.max(1,target)))+'%';$(short+'Left').textContent=sum>target?'Сверх цели '+measure(sum-target)+' г':'Осталось '+measure(target-sum)+' г'}
 let meals=dayMealList(day);$('mealCount').textContent=meals.length+' записей';$('homeMeals').innerHTML=meals.length?meals.map(mealTile).join(''):empty('За этот день пока нет записей. Добавь еду с фотографией и весом.');attachMealClicks($('homeMeals'));
}
function renderFood(){let data=person().meals.slice().sort((a,b)=>(b.date+b.created).localeCompare(a.date+a.created));let x=data.map(m=>`<div class="small muted" style="margin:12px 0 6px">${esc(dateLabel(m.date))}</div>`+mealTile(m));$('allMeals').innerHTML=x.join('')||empty('История пока пустая. Здесь появятся приёмы пищи, фото и расчёты БЖУ.');attachMealClicks($('allMeals'))}
function workoutProgress(x){const w=person().workouts.slice().sort((a,b)=>b.date.localeCompare(a.date));const sample=w.map(z=>z.items.find(i=>i.id===x.id||i.name===x.name)).filter(Boolean).slice(0,3);if(sample.length<3)return 'Прогресс: закрепляем нагрузку (нужно ≥3 тренировки)';const goal=parseInt(x.reps,10)||10;const enough=sample.every(a=>a.weight>=x.weight&&a.rir>=3&&!a.pain&&a.reps.split('/').filter(Boolean).length>=x.sets&&a.reps.split('/').every(n=>Number(n)>=goal));if(!enough)return 'Прогресс: сохраняем вес, улучшаем повторения и технику';return x.weight>0?'Можно попробовать +2–5% (одно небольшое деление)':'Можно добавить 1–2 повтора на подход';}
function renderWorkouts(){let p=person(),latest=[...(p.workouts||[])].sort((a,b)=>(b.date+b.created).localeCompare(a.date+a.created))[0];let sum=$('workoutSummary');if(p.activeWorkout){sum.innerHTML='<b>Незавершённая тренировка</b><p class="muted">'+esc(dateLabel(p.activeWorkout.date))+' · '+countDone(p.activeWorkout)+' из '+countPlanned(p.activeWorkout)+' подходов. Прогресс сохранён.</p>';}else if(latest){let performed=latest.items.filter(x=>!x.skipped&&x.reps).length,missed=latest.items.length-performed,comment=latest.feeling||'Самочувствие не указано';sum.innerHTML='<b>Последняя тренировка · '+esc(dateLabel(latest.date))+'</b><p class="muted">Упражнений выполнено: '+performed+' из '+latest.items.length+'; пропущено: '+missed+'.<br>Самочувствие: '+esc(comment)+'</p><button class="text-btn" id="openLastWorkout">Посмотреть и разобрать ›</button>';let b=$('openLastWorkout');if(b)b.onclick=()=>workoutDetail(latest.id)}else sum.innerHTML='<b>Фулбади · постепенное возвращение</b><p class="muted">Записывай фактические подходы и самочувствие. Увеличение весов — только после стабильной техники и восстановления.</p>';$('startWorkout').textContent=p.activeWorkout?'▶ Продолжить тренировку':'＋ Начать тренировку';$('planList').innerHTML=p.plan.map((x,i)=>`<div class="item"><div class="itembody"><strong>${i+1}. ${esc(x.name)}</strong><small>${x.weight?measure(x.weight)+' кг':'Свой вес'} · ${x.sets}×${esc(x.reps)}</small><small>${esc(workoutProgress(x))}</small></div><button class="text-btn" data-ex-tip="${i}" aria-label="Техника упражнения">ⓘ</button></div>`).join('');$('planList').querySelectorAll('[data-ex-tip]').forEach(b=>b.onclick=()=>openExerciseHelp(p.plan[Number(b.dataset.exTip)].name));let w=[...p.workouts].sort((a,b)=>b.date.localeCompare(a.date));$('workoutsCount').textContent=w.length+' тренировок';$('workoutList').innerHTML=w.length?w.map(x=>`<div class="item" data-workout="${esc(x.id)}"><div class="itembody"><strong>${esc(dateLabel(x.date))}</strong><small>${x.items.length} упражнений · ${esc(x.feeling||'Самочувствие не указано')}</small></div><div class="numbers"><b>Подробнее ›</b></div></div>`).join(''):empty('Записывай упражнения, фактические подходы, повторы и ощущения.');$('workoutList').querySelectorAll('[data-workout]').forEach(x=>x.onclick=()=>workoutDetail(x.dataset.workout))}
function chartMarkup(values){if(!values.length)return empty('Добавь первое измерение веса.');if(values.length===1)return `<p class="muted">Первое измерение: ${measure(values[0].weight)} кг. Для графика нужны хотя бы две даты.</p>`;let w=330,h=130,pad=13,v=values.slice(-14),min=Math.min(...v.map(x=>x.weight))-.5,max=Math.max(...v.map(x=>x.weight))+.5;let coords=v.map((x,i)=>[pad+(w-pad*2)*i/(v.length-1),h-pad-(h-2*pad)*(x.weight-min)/(max-min)]),points=coords.map(a=>a.join(',')).join(' ');return `<svg viewBox="0 0 330 155" role="img" aria-label="Изменение веса"><line x1="13" y1="120" x2="317" y2="120" stroke="#34505c"/><polyline fill="none" stroke="#b9f385" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" points="${points}"/>${coords.map(a=>`<circle cx="${a[0]}" cy="${a[1]}" r="3.5" fill="#b9f385"/>`).join('')}<text x="12" y="147">${esc(v[0].date.slice(5))}</text><text x="270" y="147">${esc(v.at(-1).date.slice(5))}</text><text x="12" y="12">${measure(max-.5)} кг</text></svg>`}
function renderTrends(){let p=person(),ms=[...p.measurements].sort((a,b)=>a.date.localeCompare(b.date)),last=ms.at(-1);$('lastWeight').textContent=last?measure(last.weight)+' кг':p.weight?measure(p.weight)+' кг':'—';$('weightDiff').textContent=ms.length>1?(ms.at(-1).weight-ms[0].weight>=0?'+':'')+measure(ms.at(-1).weight-ms[0].weight)+' кг':'—';$('chartArea').innerHTML=chartMarkup(ms);$('weightList').innerHTML=ms.length?ms.slice(-8).reverse().map(m=>`<div class="item"><div class="itembody"><strong>${esc(dateLabel(m.date))}</strong><small>Талия: ${m.waist?measure(m.waist)+' см':'не измерялась'}</small></div><div class="numbers"><b>${measure(m.weight)} кг</b></div></div>`).join(''):'';const end=last?.date||dateNow(),last7=ms.filter(z=>z.date>=shift(end,-6)&&z.date<=end),prev7=ms.filter(z=>z.date>=shift(end,-13)&&z.date<shift(end,-6)),avg=list=>list.reduce((n,z)=>n+z.weight,0)/list.length,hasTwo=last7.length>=3&&prev7.length>=3,weekly=hasTwo?avg(last7)-avg(prev7):null;
$('advice').innerHTML='<b>Как отслеживать вес без ИИ</b><p class="muted">По возможности 3–7 раз в неделю утром после туалета, до еды. Талию — 1 раз в неделю. Ориентируемся на 7-дневное среднее, а не отдельные скачки. Цели корректируем по тренду за 2–3 недели, без платного запроса при каждом взвешивании.</p>'+(last7.length>=3?'<p class="muted">Средний вес за последние 7 дней: <b>'+measure(avg(last7))+' кг</b> ('+last7.length+' замера).</p>':'<p class="muted">Для недельного среднего добавь хотя бы три утренних замера.</p>')+(hasTwo?'<p class="muted">Изменение среднего к прошлой неделе: <b>'+(weekly>0?'+':'')+measure(weekly)+' кг</b>. Это ориентир, а не диагноз или повод менять калории после одной недели.</p>':'')}
function renderSettings(){const p=person();$('profileSummary').innerHTML=[['ID для виджета',p.id],['Имя',p.name],['Рост',p.height?measure(p.height)+' см':'—'],['Вес',p.weight?measure(p.weight)+' кг':'—'],['Цель',({cut:'Снижение жира',maintain:'Поддержание',gain:'Набор мышц'})[p.goal]],['Калории',fmt(p.cal)+' ккал'],['Белок',measure(p.protein)+' г'],['Жиры',measure(p.fat)+' г'],['Углеводы',measure(p.carbs)+' г']].map(([a,b])=>`<div>${esc(a)}<strong>${esc(b)}</strong></div>`).join('');$('serviceStatus').textContent=config.url&&config.key?'НАСТРОЕНЫ':'ОТКЛЮЧЕНЫ';}
function render(){renderHome();renderFood();renderWorkouts();renderTrends();renderSettings()}
function switchTab(t){tab=t;document.querySelectorAll('.screen').forEach(x=>x.classList.toggle('active',x.id==='screen-'+t));document.querySelectorAll('.tabbar button').forEach(x=>x.classList.toggle('active',x.dataset.tab===t));window.scrollTo({top:0,behavior:'instant'});render()}
document.querySelectorAll('.tabbar button').forEach(x=>x.onclick=()=>switchTab(x.dataset.tab));document.querySelectorAll('[data-close]').forEach(x=>x.onclick=close);
$('prevDay').onclick=()=>{day=shift(day,-1);renderHome()};$('nextDay').onclick=()=>{day=shift(day,1);renderHome()};

// Photos: resized JPEGs are kept in IndexedDB, not localStorage. ZIP exports them by serialising the image store.
const PHOTO_DB='ration_plus_photos_v1';function photoDB(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window))return reject(Error('IndexedDB недоступен'));let r=indexedDB.open(PHOTO_DB,1);r.onupgradeneeded=()=>r.result.createObjectStore('pictures');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function storePhoto(id,data){let d=await photoDB();return new Promise((resolve,reject)=>{let tx=d.transaction('pictures','readwrite');tx.objectStore('pictures').put(data,id);tx.oncomplete=()=>{d.close();resolve()};tx.onerror=()=>reject(tx.error)})}
async function removePhoto(id){try{let d=await photoDB();await new Promise((resolve,reject)=>{let tx=d.transaction('pictures','readwrite');tx.objectStore('pictures').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});d.close()}catch{}}
async function getPhoto(id){let d=await photoDB();return new Promise((resolve,reject)=>{let t=d.transaction('pictures','readonly');let q=t.objectStore('pictures').get(id);q.onsuccess=()=>{d.close();resolve(q.result)};q.onerror=()=>reject(q.error)})}
async function allPhotos(){let d=await photoDB();return new Promise((resolve,reject)=>{let t=d.transaction('pictures','readonly'),q=t.objectStore('pictures').getAllKeys();q.onsuccess=async()=>{try{let out={};for(const id of q.result)out[id]=await getPhoto(id);d.close();resolve(out)}catch(e){reject(e)}};q.onerror=()=>reject(q.error)})}
function compress(file){return new Promise((resolve,reject)=>{if(!file.type.startsWith('image/'))return reject(Error('Нужна фотография'));let img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{try{const size=Math.min(1,1200/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*size));canvas.height=Math.max(1,Math.round(img.height*size));canvas.getContext('2d',{alpha:false}).drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);resolve(canvas.toDataURL('image/jpeg',.73))}catch(e){reject(e)}};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Фотография не читается'))};img.src=url})}
const photoMarkup=()=>`<div class="photo-help">${pendingPhotos.length} фото · Можно добавлять новыми порциями, максимум 30. Выбери снимок для Telegram или вариант без фото. По умолчанию выбирается последняя фотография.</div><div class="photo-strip photo-chooser">${pendingPhotos.map((x,i)=>`<div class="photo-choice ${postPhotoIndex===i?'chosen':''}"><img src="${x}" alt="Фото ${i+1}"><label><input type="radio" name="publishPhoto" value="${i}" ${postPhotoIndex===i?'checked':''}>Фото ${i+1}</label><button type="button" data-remove-photo="${i}" aria-label="Удалить фото ${i+1}">×</button></div>`).join('')}</div><label class="photo-none"><input type="radio" name="publishPhoto" value="-1" ${postPhotoIndex===-1?'checked':''}> Опубликовать в Telegram без фотографии</label>`;
function renderPhotoPicker(){const box=$('photoPreview');if(box)box.innerHTML=photoMarkup()}
function wirePhotoPicker(){const box=$('photoPreview');if(!box)return;box.addEventListener('change',e=>{if(e.target.name==='publishPhoto'){postPhotoIndex=Number(e.target.value);renderPhotoPicker()}});box.addEventListener('click',e=>{const b=e.target.closest('[data-remove-photo]');if(!b)return;const i=Number(b.dataset.removePhoto);pendingPhotos.splice(i,1);if(postPhotoIndex===i)postPhotoIndex=pendingPhotos.length-1;else if(postPhotoIndex>i)postPhotoIndex--;renderPhotoPicker()})}

/* Local food templates and individually verified products. No API call for an exact known portion. */
const normalizeFood=t=>String(t||'').toLowerCase().replace(/ё/g,'е').replace(/[.,:;!?()"']/g,' ').replace(/\s+/g,' ').trim();
const foodRows=()=>{const p=person(),list=[...(p.foodLibrary||[]),...(p.meals||[]).slice(-40).map(m=>({description:m.description,cal:m.cal,p:m.p,f:m.f,c:m.c,date:m.date}))];return [...new Map(list.filter(x=>x.description&&Number.isFinite(x.cal)).map(x=>[normalizeFood(x.description),x])).values()].slice(-35).reverse()};
function recallFood(row){if(!row)return;draftAI={cached:true};$('mDesc').value=row.description;$('manualMacros').open=true;for(const [id,k] of [['mCal','cal'],['mP','p'],['mF','f'],['mC','c']])$(id).value=Number(row[k]||0).toFixed(1);$('aiNotes').textContent='Подставлены сохранённые КБЖУ для той же порции. Если изменился вес или состав — пересчитай.';toast('Из сохранённого · без запроса к ИИ')}
function rememberMeal(m,x){const p=person();if(!Array.isArray(p.foodLibrary))p.foodLibrary=[];let key=normalizeFood(m.description);p.foodLibrary=p.foodLibrary.filter(v=>normalizeFood(v.description)!==key);p.foodLibrary.push({description:m.description,cal:m.cal,p:m.p,f:m.f,c:m.c,date:m.date});p.foodLibrary=p.foodLibrary.slice(-120);
 if(Array.isArray(x?.items)){if(!Array.isArray(p.foodCatalog))p.foodCatalog=[];for(const it of x.items){const grams=Number(it.quantityG),name=String(it.name||'').trim();if(grams<1||grams>5000||name.length<3||name.length>120||it.confidence==='low'||['cal','p','f','c'].some(k=>!Number.isFinite(it[k])||it[k]<0))continue;let entry={name,grams,cal:it.cal,p:it.p,f:it.f,c:it.c,per100:{cal:it.cal*100/grams,p:it.p*100/grams,f:it.f*100/grams,c:it.c*100/grams},origin:it.proteinOrigin||'unknown',confidence:it.confidence};p.foodCatalog=p.foodCatalog.filter(y=>normalizeFood(y.name)!==normalizeFood(name));p.foodCatalog.push(entry)}p.foodCatalog=p.foodCatalog.slice(-180)}}
function partsFromText(raw){const parts=String(raw).split(/[;,\n]+/).map(x=>x.trim()).filter(Boolean),results=[];for(const part of parts){const m=part.match(/^(.*?)\s*[—–-]?\s*(\d+(?:[.,]\d+)?)\s*г(?:рамм(?:а|ов)?)?\b/i);if(!m)return null;results.push({name:normalizeFood(m[1]),grams:num(m[2])})}return results.length?results:null}
function matchedCatalogItem(name,all){const exact=all.filter(v=>normalizeFood(v.name)===name);if(exact.length===1)return exact[0];const fuzzy=all.filter(v=>name.length>=5&&(normalizeFood(v.name).includes(name)||name.includes(normalizeFood(v.name))));return fuzzy.length===1?fuzzy[0]:null}
function calculatedFromCatalog(raw){const catalog=person().foodCatalog||[],parts=partsFromText(raw);if(!parts?.length)return null;let totals={cal:0,p:0,f:0,c:0},count=0;for(const part of parts){const hit=matchedCatalogItem(part.name,catalog);if(!hit||part.grams<=0||part.grams>4000||!hit.per100)return null;for(const key of ['cal','p','f','c'])totals[key]+=hit.per100[key]*part.grams/100;count++}return count?{description:raw,...totals}:null}
function foodFavoriteMarkup(){const rows=foodRows().slice(0,20);return `<details class="saved-foods"><summary class="manual-summary">Из сохранённых продуктов и приёмов · без оплаты ИИ</summary><div class="field"><label>Поиск по истории еды</label><input id="favoriteSearch" type="search" placeholder="Например, творог или TEOS"></div><div id="favoriteMatches" class="favorite-results">${rows.map((x,i)=>`<button type="button" class="favorite-row" data-favorite="${i}"><b>${esc(x.description.slice(0,125))}</b><small>${fmt(x.cal)} ккал · ${measure(x.p)} г белка</small></button>`).join('')||'<p class="muted">Пока нет сохранённых приёмов. После первого расчёта здесь появятся продукты.</p>'}</div><p class="muted">Сохранённые приёмы — только для прежних граммовок. По отдельным продуктам база пополняется после подтверждённого анализа этикеток.</p></details>`}
function wireFavorites(){const rows=foodRows();const box=$('favoriteMatches');if(!box)return;const paint=()=>{let q=normalizeFood($('favoriteSearch').value);box.innerHTML=rows.map((x,i)=>({x,i})).filter(o=>!q||normalizeFood(o.x.description).includes(q)).slice(0,20).map(({x,i})=>`<button type="button" class="favorite-row" data-favorite="${i}"><b>${esc(x.description.slice(0,125))}</b><small>${fmt(x.cal)} ккал · ${measure(x.p)} г белка</small></button>`).join('')||'<p class="muted">Ничего не найдено.</p>'};$('favoriteSearch').oninput=paint;box.onclick=e=>{let btn=e.target.closest('[data-favorite]');if(btn){recallFood(rows[Number(btn.dataset.favorite)]);$('favoriteSearch').value='';paint()}}}

let currentMealEdit=null;
function mealFields(m={}){return `<div class="field"><label>Когда и что ел</label><div class="fields"><input type="date" id="mDate" value="${esc(m.date||day)}"><select id="mType"><option>Завтрак</option><option>Обед</option><option>Ужин</option><option>Перекус</option></select></div></div><div class="field"><label>Название / продукты с весами</label><textarea id="mDesc" placeholder="Куриная грудка — 205 г, булгур — 80 г сухого веса…">${esc(m.description||'')}</textarea><div class="hint">Указывай сухой/готовый вес и состав; фото упаковки и этикетки повышают точность.</div></div><div class="field"><label>Фото блюда, упаковок и этикеток (до 30; можно добавлять частями)</label><input type="file" id="mPhotos" accept="image/*" multiple><div id="photoPreview" class="photo-strip"></div></div>${foodFavoriteMarkup()}<div class="actions">${btn('analyze','✦ Рассчитать по фото и описанию','outline')}</div><label class="muted"><input type="checkbox" id="allowProductWebSearch"> Если нет этикетки и данных в базе — разрешить поиск продукта в интернете (может увеличить стоимость)</label><div class="s-note" id="aiNotes">Без подключения сервера доступен ручной ввод. Результаты ИИ — оценка: обязательно сверь этикетку и вес.</div><div class="source-links" id="aiSources"></div><details id="manualMacros" ${m.id?'open':''}><summary class="manual-summary">Результат расчёта · калории и БЖУ (можно поправить)</summary><div class="fields">${field('Калории · ккал','mCal',m.cal??'','number','inputmode="decimal" min="0" step="0.1"')}${field('Белок · г','mP',m.p??'','number','inputmode="decimal" min="0" step="0.1"')}${field('Жиры · г','mF',m.f??'','number','inputmode="decimal" min="0" step="0.1"')}${field('Углеводы · г','mC',m.c??'','number','inputmode="decimal" min="0" step="0.1"')}</div></details><label class="muted"><input type="checkbox" id="autoPost" ${config.autoPost!==false?'checked':''}> После сохранения показать предварительный пост Telegram (ничего не отправлять без отдельного подтверждения)</label><div class="actions">${btn('saveMeal','✓ Сохранить приём')}${btn('cancelMeal','Отмена','outline')}</div>`}
async function openMeal(id=null){let existing=id?person().meals.find(x=>x.id===id):null;currentMealEdit=id;pendingPhotos=[];postPhotoIndex=-1;if(existing){for(const pid of (existing.photoIds||[])){let data=await getPhoto(pid);if(data)pendingPhotos.push(data)};postPhotoIndex=existing.postPhotoId?Math.max(-1,(existing.photoIds||[]).indexOf(existing.postPhotoId)):(existing.postPhotoId===null?-1:pendingPhotos.length-1)}
modal(existing?'Изменить приём пищи':'Новый приём пищи',mealFields(existing||{}),()=>{let mType=$('mType');mType.value=existing?.mealType||'Обед';renderPhotoPicker();wirePhotoPicker();wireFavorites();$('mPhotos').onchange=async e=>{const files=Array.from(e.target.files||[]);if(!files.length)return;if(pendingPhotos.length+files.length>30){toast('Максимум 30 фотографий за один приём');return}try{let batch=[];for(const f of files)batch.push(await compress(f));pendingPhotos.push(...batch);postPhotoIndex=pendingPhotos.length-1;renderPhotoPicker();toast('Добавлено фото: '+batch.length)}catch(err){toast(err.message)}finally{e.target.value=''}};$('cancelMeal').onclick=close;$('analyze').onclick=analyzeMeal;$('saveMeal').onclick=saveMeal})}
async function api(path,data,read=false){if(!config.url||!config.key)throw Error('Сначала подключи сервер в Профиль → Подключения');const u=config.url.replace(/\/$/,'')+path;const r=await fetch(u,{method:read?'GET':'POST',headers:{Authorization:'Bearer '+config.key,...(read?{}:{'Content-Type':'application/json'})},...(read?{}:{body:JSON.stringify(data)})});let payload=await r.json().catch(()=>({}));if(!r.ok)throw Error(payload.error||`Ошибка сервера ${r.status}`);return payload}
async function analyzeMeal(){if(busy)return;const description=$('mDesc').value.trim();if(!description&&!pendingPhotos.length)return toast('Добавь описание или фото');
if(!pendingPhotos.length){let known=foodRows().find(x=>normalizeFood(x.description)===normalizeFood(description))||calculatedFromCatalog(description);if(known){recallFood(known);return}}
busy=true;$('analyze').textContent='Анализирую…';$('analyze').disabled=true;try{let data=await api('/api/analyze',{description,photos:pendingPhotos,mealType:$('mType').value,knownFoods:(person().foodCatalog||[]).slice(-18),allowWebSearch:$('allowProductWebSearch').checked});let x=data.meal||data;draftAI=x;$('mDesc').value=x.description||description;$('manualMacros').open=true;for(const [id,prop] of [['mCal','cal'],['mP','p'],['mF','f'],['mC','c']])$(id).value=Number(x[prop]||0).toFixed(1);$('aiNotes').textContent=(x.notes||'')+' · Источник: '+(x.source||'оценка ИИ')+' · Точность: '+(x.confidence||'неизвестна')+'. Исправь значения при необходимости.';const linkBox=$('aiSources');if(linkBox)linkBox.innerHTML=(x.sources||[]).filter(v=>/^https:\/\//.test(v)).slice(0,5).map(v=>'<a rel="noopener noreferrer" target="_blank" href="'+esc(v)+'">Источник по продукту ↗</a>').join(' · ');toast('Оценка готова — проверь перед сохранением')}catch(e){toast(e.message)}finally{busy=false;let b=$('analyze');if(b){b.textContent='✦ Рассчитать по фото и описанию';b.disabled=false}}}
const telegramCaption=m=>`${m.mealType}: ${m.description.trim().replace(/[.\\s]+$/,'')||m.name}.\n\n≈${fmt(m.cal)} ккал, белка ≈${measure(m.p)} г.`;
async function postMeal(m,captionOverride=null,photoOverride=undefined){const selected=photoOverride===undefined?m.postPhotoId:photoOverride;const pic=selected?await getPhoto(selected):null;const caption=captionOverride===null?telegramCaption(m):String(captionOverride).trim();let r=await api('/api/telegram',{caption,photo:pic,mealId:m.id});m.posted=true;m.telegramId=r.messageId||null;save();render();return r}
async function previewTelegram(m){if(m.posted)return toast('Эта запись уже опубликована');modal('Проверить пост для Telegram',`<p class="muted">Это только предпросмотр. Пока не нажмёшь «Отправить», публикации не будет.</p><div class="field"><label>Текст сообщения (можно изменить)</label><textarea id="tgCaption" rows="5">${esc(telegramCaption(m))}</textarea></div><div id="tgPhotoPreview" class="photo-strip"></div><div class="field"><label for="tgPhotoChoice">Фотография для публикации</label><select id="tgPhotoChoice"><option value="">Без фотографии</option>${(m.photoIds||[]).map((pid,i)=>`<option value="${esc(pid)}" ${pid===m.postPhotoId?'selected':''}>Фото ${i+1}</option>`).join('')}</select></div><div class="actions">${btn('tgSend','Отправить в Telegram')}${btn('tgCancel','Не публиковать','outline')}</div>`,()=>{const select=$('tgPhotoChoice');select.value=m.postPhotoId||'';const preview=async()=>{let id=select.value,box=$('tgPhotoPreview');if(!box)return;if(!id){box.innerHTML='<p class="muted">Публикация без фотографии</p>';return}let src=await getPhoto(id);if(box.isConnected)box.innerHTML=src?`<img src="${src}" alt="Выбранная фотография для Telegram">`:''};select.onchange=preview;preview();$('tgCancel').onclick=close;$('tgSend').onclick=async()=>{if(busy)return;let caption=$('tgCaption').value.trim(),pid=select.value||null;if(!caption)return toast('Добавь текст сообщения');busy=true;$('tgSend').disabled=true;try{await postMeal(m,caption,pid);m.postPhotoId=pid;save();busy=false;close();render();toast('Пост опубликован в Telegram')}catch(e){busy=false;$('tgSend').disabled=false;toast('Не отправлено: '+e.message)}}})}
async function syncWidget(){if(!config.url||!config.key)return;const p=person(),s=sums(dateNow());try{await api('/api/progress',{profileId:p.id,date:dateNow(),name:p.name,cal:round(s.cal),protein:fixed(s.p),fat:fixed(s.f),carbs:fixed(s.c),goalCal:p.cal,goalProtein:p.protein})}catch(e){console.warn('Widget sync unavailable',e.message)}}
async function saveMeal(){if(busy)return;let vals={date:$('mDate').value,mealType:$('mType').value,description:$('mDesc').value.trim(),cal:num($('mCal').value),p:num($('mP').value),f:num($('mF').value),c:num($('mC').value)};if(!/^\d{4}-\d\d-\d\d$/.test(vals.date)||!vals.description||['mCal','mP','mF','mC'].some(id=>!$(id).value.trim())||[vals.cal,vals.p,vals.f,vals.c].some(x=>!Number.isFinite(x)||x<0||x>10000))return toast('Нужно описание и все четыре значения БЖУ, даже если они равны нулю');if(vals.cal===0&&vals.p===0&&vals.f===0&&vals.c===0)return toast('Проверь калории и БЖУ перед сохранением');const macroEnergy=vals.p*4+vals.f*9+vals.c*4;if(Math.abs(macroEnergy-vals.cal)>Math.max(100,vals.cal*.25)&&!confirm('Сумма калорий из БЖУ существенно отличается от указанной калорийности. Это возможно для продуктов с клетчаткой и полиолами. Сохранить как есть?'))return;
 const old=currentMealEdit?person().meals.find(x=>x.id===currentMealEdit):null;let m={...old,...vals,id:old?.id||uid(),created:old?.created||new Date().toISOString(),name:vals.description.split(',')[0].slice(0,60),source:draftAI?.cached?'Из локальной базы':draftAI?'ИИ — проверено пользователем':'Внесено вручную',photoIds:[],postPhotoId:null,posted:old?.posted||false};busy=true;$('saveMeal').disabled=true;try{for(const photo of pendingPhotos){let id=uid();await storePhoto(id,photo);m.photoIds.push(id)}m.postPhotoId=postPhotoIndex>=0?m.photoIds[postPhotoIndex]||null:null;const list=person().meals,idx=old?list.findIndex(x=>x.id===old.id):-1;if(idx<0)list.push(m);else list[idx]=m;if(old)for(const pid of old.photoIds||[])removePhoto(pid);rememberMeal(m,draftAI);save();let shouldPost=$('autoPost').checked;config.autoPost=shouldPost;saveConfig();closeWhenFree();render();await syncWidget();if(shouldPost&&!m.posted){await previewTelegram(m)}else toast('Приём пищи сохранён');}catch(e){toast('Ошибка сохранения: '+e.message)}finally{busy=false}}
function closeWhenFree(){busy=false;close();busy=true}
function mealDetail(id){let m=person().meals.find(x=>x.id===id);if(!m)return;modal('Приём пищи',`<div class="s-note"><b>${esc(m.mealType)}</b> · ${esc(dateLabel(m.date))}</div><p class="compact">${esc(m.description)}</p><div class="photo-strip" id="detailPhotos"></div><div class="statcards"><div class="stat"><span>Калории</span><b>${fmt(m.cal)}</b></div><div class="stat"><span>Белок, г</span><b>${measure(m.p)}</b></div><div class="stat"><span>Жиры, г</span><b>${measure(m.f)}</b></div><div class="stat"><span>Углеводы, г</span><b>${measure(m.c)}</b></div></div><div class="s-note">${esc(m.source)}${m.posted?' · Опубликовано в Telegram (изменения здесь не редактируют уже опубликованный пост)':''}</div><div class="actions">${btn('editMeal','Изменить','outline')}${btn('postMealBtn',m.posted?'Уже опубликовано ✓':'Предпросмотр Telegram',m.posted?'outline':'primary')}${btn('deleteMeal','Удалить','danger')}</div>`,()=>{let strip=$('detailPhotos');(m.photoIds||[]).forEach(async id=>{let data=await getPhoto(id);if(data&&strip?.isConnected){let img=document.createElement('img');img.src=data;strip.append(img)}});$('editMeal').onclick=()=>openMeal(m.id);$('deleteMeal').onclick=()=>{if(!confirm('Удалить этот приём пищи?'))return;person().meals=person().meals.filter(x=>x.id!==m.id);(m.photoIds||[]).forEach(removePhoto);save();close();render();syncWidget();toast('Удалено')};$('postMealBtn').disabled=!!m.posted;$('postMealBtn').onclick=async()=>{if(m.posted)return;const btn=$('postMealBtn');btn.disabled=true;try{await previewTelegram(m)}catch(e){toast(e.message);btn.disabled=false}}})}
$('quickAdd').onclick=$('newMeal').onclick=()=>openMeal();$('foodImport').onclick=$('importData').onclick=importBackup;

function profileSwitch(){modal('Выбор профиля',`<div class="list">${db.profiles.map(p=>`<button class="btn ${p.id===person().id?'primary':'outline'}" data-profile="${esc(p.id)}">${esc(p.name)}</button>`).join('')}</div><div class="hr"></div><div class="field"><label>Новый профиль (например, Ника)</label><input id="newProfileName" maxlength="34" placeholder="Имя"></div>${btn('newProfileBtn','＋ Добавить профиль')}`,()=>{document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>{db.selectedProfile=b.dataset.profile;day=dateNow();save();close();render();toast('Профиль переключён')});$('newProfileBtn').onclick=()=>{let name=$('newProfileName').value.trim();if(!name)return toast('Введи имя');let p=makeProfile(name,false);db.profiles.push(p);db.selectedProfile=p.id;save();close();editProfile()}})}
$('profileSwitch').onclick=profileSwitch;
function editProfile(){let p=person();modal('Профиль и цели',`${field('Имя','prName',p.name,'text','maxlength="34"')}<div class="fields">${field('Рост, см','prHeight',p.height||'','number','min="120" max="230"')}${field('Вес, кг','prWeight',p.weight||'','number','step="0.1" min="30" max="300"')}</div><div class="fields">${field('Возраст, лет','prAge',p.age||'','number','min="16" max="100"')}<div class="field"><label>Формула обмена</label><select id="prSex"><option value="male">Мужская</option><option value="female">Женская</option></select></div></div><div class="fields"><div class="field"><label>Цель</label><select id="prGoal"><option value="cut">Снижение жира</option><option value="maintain">Поддержание</option><option value="gain">Набор мышц</option></select></div><div class="field"><label>Активность</label><select id="prActivity"><option value="1.2">Малоподвижная</option><option value="1.375">Лёгкая · 2–3 тренировки</option><option value="1.55">Умеренная</option><option value="1.7">Высокая</option></select></div></div><div class="fields">${field('Калории, ккал/день','prCal',p.cal)}${field('Белок, г','prProtein',p.protein)}${field('Жиры, г','prFat',p.fat)}${field('Углеводы, г','prCarbs',p.carbs)}</div><div class="field"><label>Тренировочный этап</label><select id="prPhase"><option value="return">Постепенно возвращаюсь после перерыва</option><option value="steady">Обычный тренировочный режим</option></select></div><div class="s-note">Цели редактируются вручную. Подсчёт по формуле — предварительная оценка, а не измерение обмена веществ.</div><div class="actions">${btn('prSave','Сохранить')}${btn('prSuggest','Рассчитать ориентир','outline')}</div>`,()=>{$('prSex').value=p.sex;$('prGoal').value=p.goal;$('prActivity').value=String(p.activity);$('prPhase').value=p.trainingPhase||'return';$('prSuggest').onclick=()=>{let estimate=calculateGoals(true);if(estimate){$('prCal').value=estimate.cal;$('prProtein').value=estimate.protein;$('prFat').value=estimate.fat;$('prCarbs').value=estimate.carbs;toast('Ориентир заполнен — можешь его изменить')}};$('prSave').onclick=()=>{let name=$('prName').value.trim(),height=num($('prHeight').value),weight=num($('prWeight').value),age=num($('prAge').value),cal=num($('prCal').value),protein=num($('prProtein').value),fat=num($('prFat').value),carbs=num($('prCarbs').value);if(!name||cal<900||cal>6000||protein<0||protein>400||fat<0||fat>300||carbs<0||carbs>900||(height&&(height<120||height>230))||(weight&&(weight<30||weight>300))||(age&&(age<16||age>100)))return toast('Проверь значения в полях');Object.assign(p,{name,height:height||null,weight:weight||null,age:age||null,sex:$('prSex').value,goal:$('prGoal').value,activity:num($('prActivity').value),trainingPhase:$('prPhase').value,cal,protein,fat,carbs});save();close();render();syncWidget();toast('Цели и профиль обновлены')}})}
function calculateGoals(show=false){let w=num($('prWeight')?.value||person().weight),h=num($('prHeight')?.value||person().height),age=num($('prAge')?.value||person().age),sex=$('prSex')?.value||person().sex,factor=num($('prActivity')?.value||person().activity),goal=$('prGoal')?.value||person().goal;if(!w||!h||!age){toast('Для расчёта укажи вес, рост и возраст');return null}const bmr=10*w+6.25*h-5*age+(sex==='male'?5:-161),tdee=bmr*factor,cal=Math.round((goal==='cut'?tdee*.90:goal==='gain'?tdee*1.06:tdee)/50)*50,protein=Math.round(w*(goal==='cut'?2:goal==='gain'?1.8:1.6)),fat=Math.round(.85*w),carbs=Math.max(0,Math.round((cal-4*protein-9*fat)/4));if(show)toast('Расчёт: расход ≈'+fmt(tdee)+' ккал. Приоритет — тренд веса и талии за 2–3 недели.');return{cal,protein,fat,carbs,bmr,tdee}}
$('profileEdit').onclick=editProfile;$('goalRecalc').onclick=()=>{editProfile();setTimeout(()=>{$('prSuggest')?.focus()},100)};

function recordWeight(){let p=person();modal('Измерения',`<div class="field"><label>Дата</label><input type="date" id="wDate" value="${dateNow()}"></div><div class="fields">${field('Вес, кг','wWeight',p.weight||'','number','min="20" max="300" step="0.1"')}${field('Талия, см (необязательно)','wWaist','','number','min="35" max="250" step="0.1"')}</div>${btn('wSave','Сохранить измерение')}`,()=>{$('wSave').onclick=()=>{let date=$('wDate').value,w=num($('wWeight').value),waist=num($('wWaist').value);if(!date||w<25||w>300||(waist&&(waist<35||waist>250)))return toast('Проверь измерения');p.measurements=p.measurements.filter(m=>m.date!==date);p.measurements.push({date,weight:w,waist:waist||null});p.measurements.sort((a,b)=>a.date.localeCompare(b.date));p.weight=p.measurements.at(-1).weight;save();close();render();toast('Вес сохранён без обращения к ИИ')}})}
$('recordWeight').onclick=recordWeight;
function editProgram(){let p=person();modal('Моя программа',`<p class="muted">Измени рабочие веса, подходы и повторы. Изолирующие упражнения можно добавить позже.</p><div id="programRows">${p.plan.map((x,i)=>`<div class="surface compact" data-program="${esc(x.id)}"><label class="muted"><input type="checkbox" class="progEnabled" checked> В программе</label><div class="field"><label>Упражнение ${i+1}</label><input class="progName" type="text" value="${esc(x.name)}"></div><div class="fields">${field('Вес, кг','pw'+i,x.weight)}${field('Подходы','ps'+i,x.sets)}</div>${field('Повторы','pr'+i,x.reps,'text')}</div>`).join('')}</div><div class="actions">${btn('saveProgram','Сохранить программу')}${btn('addExercise','＋ Упражнение','outline')}</div>`,()=>{let items=p.plan.map(x=>({...x}));$('addExercise').onclick=()=>{items.push({id:uid(),name:'Новое упражнение',weight:0,sets:2,reps:'12'});let i=items.length-1;let wrap=document.createElement('div');wrap.innerHTML=`<div class="surface compact"><label class="muted"><input type="checkbox" class="progEnabled" checked> В программе</label><div class="field"><label>Упражнение ${i+1}</label><input class="progName" type="text" value="Новое упражнение"></div><div class="fields">${field('Вес, кг','pw'+i,0)}${field('Подходы','ps'+i,2)}</div>${field('Повторы','pr'+i,'12','text')}</div>`;$('programRows').append(wrap.firstElementChild)};$('saveProgram').onclick=()=>{let nodes=$('programRows').querySelectorAll('.surface'),next=[...nodes].map((n,i)=>({id:items[i].id,name:n.querySelector('.progName').value.trim(),weight:num($('pw'+i).value),sets:num($('ps'+i).value),reps:$('pr'+i).value.trim(),enabled:n.querySelector('.progEnabled').checked})).filter(x=>x.enabled);if(next.some(x=>!x.name||x.weight<0||x.weight>600||x.sets<1||x.sets>9||!x.reps))return toast('Проверь программу');if(!next.length)return toast('Оставь хотя бы одно упражнение');p.plan=next;save();close();render();toast('Программа обновлена')}})}
$('editProgram').onclick=editProgram;

/* Paste a simple text workout plan from iPhone Notes; user confirms parsed weights before replacing plan. */
function parseProgramNotes(raw){let out=[];for(let line of String(raw||'').split(/\r?\n/)){line=line.trim().replace(/^\s*(?:[0-9]{1,2}[.)]|[-*•])\s*/,'');if(!line||/^\s*(?:разминка|комментарий|итого|логика)\s*:/i.test(line))continue;
 const columns=line.split(/\t+/);if(columns.length>=3){const match=columns[1].trim().match(/^(\d+)\s*\/\s*(\d+)/),w=Number(columns[2].trim().replace(',','.'));if(match&&columns[0].trim().length>=3){out.push({id:uid(),name:columns[0].trim(),weight:Number.isFinite(w)?w:0,sets:Number(match[1]),reps:match[2]});continue}}
 const weightMatch=line.match(/(\d+(?:[.,]\d+)?)\s*кг/i),setMatch=line.match(/(\d+)\s*[хx×*]\s*(\d+(?:\s*[-–]\s*\d+)?)/i);if(!weightMatch&&!setMatch)continue;
 const first=Math.min(weightMatch?.index??1e6,setMatch?.index??1e6);const name=line.slice(0,first).replace(/\s*[—–:;,]\s*$/,'').trim();if(name.length<3||name.length>90)continue;
 const sets=setMatch?Number(setMatch[1]):2,reps=setMatch?setMatch[2].replace(/\s+/g,''):'12',weight=weightMatch?num(weightMatch[1]):0;
 if(sets<1||sets>9||weight<0||weight>600)continue;
 out.push({id:uid(),name,weight,sets,reps})}
 return out.slice(0,30)}

function parseCompletedWorkout(raw,optionalDate=dateNow()){const dateToken=String(raw).match(/Тренировка\s+(\d{1,2})[.]([0-1]?\d)[.](\d{2,4})/i);const parsedDate=dateToken?(dateToken[3].length===2?'20':'')+dateToken[3]+'-'+dateToken[2].padStart(2,'0')+'-'+dateToken[1].padStart(2,'0'):optionalDate;
 const result={date:parsedDate,items:[],feeling:'',effort:null,steps:null,source:'Заметки iPhone'};
 for(const row of String(raw).split(/\r?\n/)){const cols=row.split(/\t+/).map(x=>x.trim());if(cols.length<3||cols[0].length<3)continue;const status=cols[1].toLowerCase(),done=status.includes('все сделал')||status.includes('всё сделал')||status.includes('выполн'),skipped=status.includes('пропуск'),set=status.match(/^(\d+)\s*\/\s*(\d+)/);if(!set&&!skipped)continue;
 const weight=Number(cols[2].replace(',','.')),sets=set?Number(set[1]):0,reps=set?Number(set[2]):0;
 result.items.push({id:uid(),name:cols[0],weight:Number.isFinite(weight)?weight:0,setsPlanned:sets,setsDone:done?sets:0,reps:done?Array(sets).fill(reps).join('/'):'' ,rir:null,pain:false,skipped:!done,comment:skipped?'Пропуск по заметкам':''})}
 return result}

function importProgramNotes(){let draft=[];modal('Импорт программы из заметок',`<p class="muted">Скопируй текст из «Заметок» iPhone или прикрепи файл .txt. Пример: «Гакк-присед — 50 кг — 2×10». Сначала проверь распознанную программу — существующая не изменится до подтверждения.</p><div class="field"><label>Текст заметок</label><textarea id="notesRaw" rows="9" placeholder="Гакк-присед — 50 кг — 2×10&#10;Жим от груди — 15 кг — 2×12"></textarea></div><div class="field"><label>Или загрузить текстовый файл</label><input id="notesFile" type="file" accept=".txt,text/plain"></div><div id="parsedNotes" class="s-note">Пока ничего не загружено.</div><div class="actions">${btn('parseNotes','Показать распознанное','outline')}${btn('applyNotes','Заменить программу','primary')}${btn('cancelNotes','Отмена','outline')}</div>`,()=>{$('applyNotes').disabled=true;$('notesFile').onchange=async e=>{let f=e.target.files?.[0];if(f){$('notesRaw').value=(await f.text()).slice(0,20000);toast('Заметки загружены — нажми «Показать распознанное»')}};$('parseNotes').onclick=()=>{draft=parseProgramNotes($('notesRaw').value);$('applyNotes').disabled=!draft.length;$('parsedNotes').innerHTML=draft.length?'<b>Проверь веса и подходы:</b><ol>'+draft.map(x=>`<li>${esc(x.name)} — ${measure(x.weight)} кг, ${x.sets}×${esc(x.reps)}</li>`).join('')+'</ol><small>Не загружает историю тренировок; только заменяет текущую программу.</small>':'Не удалось найти упражнения. Используй формат «Название — 50 кг — 2×12».'};$('applyNotes').onclick=()=>{if(!draft.length)return;if(!confirm('Заменить текущую программу '+draft.length+' упражнениями из заметок? История прошлых тренировок сохранится.'))return;person().plan=draft;save();close();render();toast('Программа из заметок сохранена')};$('cancelNotes').onclick=close})}
$('importProgramNotes').onclick=importProgramNotes;


/* Offline-first live training: sets are unchecked until performed. One optional AI call after finishing. */
const TRAIN_TIPS=[
 [/гак|жим ногами/i,['Настрой положение так, чтобы спина и таз оставались прижаты к опоре.','Колени двигай по линии стоп. Опускай платформу в контролируемом темпе до комфортной глубины.','Выжимай платформу без рывка и без резкого выпрямления коленей. Не задерживай дыхание.']],
 [/ягодичн.*мост/i,['Опирайся верхом спины на скамью или спинку тренажёра, стопы устойчиво на полу.','Разгибай таз преимущественно ягодицами, не прогибай чрезмерно поясницу.','Опускай таз плавно, держи шею нейтрально.']],
 [/вертикальн.*тяг/i,['Слегка отведи плечи вниз, корпус устойчив, без раскачки.','Тяни рукоять к верхней части груди, веди локти вниз.','Возвращай рукоять контролируемо; не тяни за голову.']],
 [/горизонтальн.*тяг/i,['Сядь устойчиво, сохрани нейтральное положение спины.','Тяни рукоять к нижней части груди или животу, отводя локти назад.','Не округляй поясницу и не подбрасывай вес корпусом.']],
 [/жим.*груд/i,['Прижми лопатки к опоре, стопы поставь устойчиво.','Жми рукояти без рывка, локти не разводи строго в стороны.','Возвращай вес плавно, не теряя контроля в нижней точке.']],
 [/сгибан.*ног/i,['Совмести ось колена с осью тренажёра, удерживай таз на подушке.','Плавно сгибай колени без рывков и без подъёма таза.','Не допускай удара грузов при обратном движении.']],
 [/обратн.*бабочк/i,['Установи рукояти так, чтобы плечам было комфортно.','Разводи руки назад, удерживая опущенные плечи.','Не выгибай поясницу и не тяни вес рывком.']],
 [/бабочк/i,['Держи плечи опущенными, грудь устойчиво прижата к спинке.','Своди рукояти перед собой плавно, не своди плечи вверх.','Возвращай руки до комфортного растяжения грудных мышц.']],
 [/отведен.*рук/i,['Встань устойчиво, слегка согни локоть.','Поднимай руку в сторону до уровня плеч или ниже при дискомфорте.','Без раскачки корпуса и подъёма плеча к уху.']],
 [/пресс|подъём.*колен|перекладин/i,['Зафиксируй плечи, не раскачивай тело.','Поднимай колени контролируемо за счёт сгибания таза и напряжения живота.','Опускай ноги плавно. Если плечам тяжело — замени на подъём коленей лёжа.']]
];
function exerciseTip(name){return TRAIN_TIPS.find(([rx])=>rx.test(name))?.[1]||['Подбери положение тренажёра под себя.','Используй контролируемую амплитуду и вес без рывков.','При боли в суставе, резкой головной боли или головокружении остановись.']}
function openExerciseHelp(name,backToWorkout=false){const cues=exerciseTip(name);modal('Техника: '+name,`<ol class="tech-cues">${cues.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p class="muted">Краткая памятка, а не замена показу техники тренером. На следующем этапе можно добавить схемы движений для каждого тренажёра.</p>${btn('helpClose','Понятно','outline')}`,()=>{$('helpClose').onclick=()=>backToWorkout?startWorkout():close()})}
function createWorkoutDraft(p){return{id:uid(),date:dateNow(),created:new Date().toISOString(),items:p.plan.map(x=>({id:x.id,name:x.name,weight:x.weight,sets:x.sets,targetReps:x.reps,done:Array.from({length:x.sets},()=>false),actual:Array.from({length:x.sets},()=>parseInt(x.reps,10)||10),rir:3,pain:false,comment:'',skipped:false})),feeling:'',effort:'moderate',steps:null}}
const countDone=d=>d.items.reduce((a,x)=>a+x.done.filter(Boolean).length,0);
const countPlanned=d=>d.items.reduce((a,x)=>a+x.sets,0);
function persistWorkoutDraft(){save();const n=$('wkCounter');if(n){const d=person().activeWorkout;n.textContent=d?`${countDone(d)} из ${countPlanned(d)} подходов`:''}}
function workoutEditor(d){const t=sums(d.date),energy=t.cal? `По дневнику за сегодня внесено ${fmt(t.cal)} ккал. Если записи неполные, это не фактическое питание за день.`:'Сегодня питание в дневник ещё не внесено; не считай ноль доказательством, что ты ничего не ел.';
 return `<div class="workout-progress"><b id="wkCounter">${countDone(d)} из ${countPlanned(d)} подходов</b><small>План уже подготовлен. Нажимай «Сделал», только когда закончил подход. Всё сохраняется на телефоне.</small></div><div class="s-note">${esc(energy)} <br>Сейчас — фаза постепенного возвращения, если она включена в профиле.</div>
 <div class="field"><label>Дата</label><input id="wkDate" type="date" value="${esc(d.date)}"></div>
 <div id="liveExercises">${d.items.map((x,i)=>`<section class="live-exercise" data-exercise="${i}"><div class="row"><b>${i+1}. ${esc(x.name)}</b><button type="button" class="text-btn" data-tech="${i}" aria-label="Техника упражнения">ⓘ Техника</button></div>
 <div class="fields"><div class="field"><label>Рабочий вес, кг</label><input type="number" inputmode="decimal" min="0" max="600" step="0.1" data-weight="${i}" value="${String(x.weight).replace(',','.')}"></div>
 <div class="field"><label>План</label><div class="target-reps">${x.sets}×${esc(x.targetReps)} повторов</div></div></div>
 <div class="sets-grid">${x.done.map((done,j)=>`<div class="set-row"><span>Подход ${j+1}</span><input aria-label="Повторы в подходе ${j+1}" type="number" min="0" max="100" inputmode="numeric" data-reps="${i}-${j}" value="${x.actual[j]}"><button type="button" class="set-check ${done?'is-done':''}" data-set="${i}-${j}" aria-pressed="${done?'true':'false'}">${done?'✓ Сделал':'○ Сделал'}</button></div>`).join('')}</div>
 <div class="fields"><div class="field"><label>Повторов в запасе (после упражнения)</label><select data-rir="${i}">${[4,3,2,1,0].map(z=>`<option value="${z}" ${x.rir===z?'selected':''}>${z===4?'4+':z}${z===0?' (отказ)':''}</option>`).join('')}</select></div>
 <div class="field"><label>Дискомфорт</label><select data-pain="${i}"><option value="no" ${!x.pain?'selected':''}>Нет</option><option value="yes" ${x.pain?'selected':''}>Был</option></select></div></div>
 <div class="field"><label>Заметка по упражнению (необязательно)</label><input type="text" data-comment="${i}" maxlength="250" value="${esc(x.comment||'')}" placeholder="Тяжело, хорошая техника…"></div><label class="skip-check"><input type="checkbox" data-skip="${i}" ${x.skipped?'checked':''}> Пропустить упражнение</label>
 </section>`).join('')}</div>
 <div class="field"><label>Самочувствие и общие ощущения</label><textarea id="wkFeeling" placeholder="Гакк умеренно; голова не болела; к концу устал…">${esc(d.feeling||'')}</textarea></div><div class="fields"><div class="field"><label>Ощущаемая нагрузка</label><select id="wkEffort"><option value="easy" ${d.effort==='easy'?'selected':''}>Легко</option><option value="moderate" ${d.effort==='moderate'?'selected':''}>Умеренно</option><option value="hard" ${d.effort==='hard'?'selected':''}>Тяжело</option></select></div><div class="field"><label>Шаги за день (необязательно)</label><input id="wkSteps" type="number" min="0" max="100000" inputmode="numeric" value="${d.steps??''}" placeholder="Нет данных"></div></div>
 <div class="actions">${btn('wkPause','Сохранить и выйти','outline')}${btn('wkFinish','Завершить тренировку')}</div>`;}

function displayPlanSuggestion(p){const x=p.planSuggestion;if(!x)return;let txt=x.exercisePlan.map(i=>i.name+' — '+measure(i.weight)+' кг — '+i.sets+'×'+i.reps).join('\n');modal('ИИ-план · проверь перед применением',`<div class="s-note"><b>Почему такой план</b><p>${esc(x.summary)}</p><p>${esc(x.timing)}</p></div><div class="field"><label>Упражнение — вес — подходы×повторы</label><textarea id="aiPlanText" rows="12">${esc(txt)}</textarea></div>${x.risks?.length?'<div class="caution">'+x.risks.map(esc).join('<br>')+'</div>':''}<div class="actions">${btn('applyAiPlan','Принять программу')}${btn('cancelAiPlan','Оставить прежнюю','outline')}${btn('refreshAiPlan','Пересчитать','outline')}</div>`,()=>{$('applyAiPlan').onclick=()=>{let parsed=parseProgramNotes($('aiPlanText').value);if(!parsed.length)return toast('Проверь формат плана');if(person().activeWorkout)return toast('Сначала заверши текущую тренировку');if(!confirm('Заменить текущую программу, сохранив историю тренировок?'))return;p.plan=parsed;p.planSuggestion=null;save();close();render();toast('Программа обновлена')};$('cancelAiPlan').onclick=close;$('refreshAiPlan').onclick=()=>suggestProgram(true)})}
async function suggestProgram(force=false){if(!config.url||!config.key)return toast('ИИ доступен после подключения сервера в Профиле');const p=person();if(p.activeWorkout)return toast('Заверши текущую тренировку перед сменой программы');if(p.planSuggestion&&!force){displayPlanSuggestion(p);return}if(busy)return;busy=true;const b=$('aiProgram');if(b){b.disabled=true;b.textContent='Составляю…'}try{const history=[...(p.workouts||[])].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8),today=dateNow();const res=await api('/api/program-suggest',{profile:{height:p.height,weight:p.weight,age:p.age,goal:p.goal,trainingPhase:p.trainingPhase||'return',targetCal:p.cal,targetProtein:p.protein},plan:p.plan,history,meals:p.meals.filter(x=>x.date===today).map(x=>({description:x.description,cal:x.cal,p:x.p,f:x.f,c:x.c})),steps:history[0]?.date===today?history[0]?.steps??null:null});p.planSuggestion=res.plan;save();busy=false;displayPlanSuggestion(p)}catch(e){busy=false;toast('Не удалось составить программу: '+e.message)}finally{if(b){b.disabled=false;b.textContent='ИИ-план'}}}
$('aiProgram').onclick=()=>suggestProgram();

function startWorkout(){let p=person();if(!p.activeWorkout){if(!p.plan?.length){toast('Добавь программу через «Из заметок» или «Настроить»');return}p.activeWorkout=createWorkoutDraft(p);save()}
 const d=p.activeWorkout;modal('Тренировка · по подходам',workoutEditor(d),()=>{const body=$('modalBody');body.addEventListener('click',e=>{const info=e.target.closest('[data-tech]');if(info){persistWorkoutDraft();openExerciseHelp(d.items[Number(info.dataset.tech)].name,true);return}const btn=e.target.closest('[data-set]');if(!btn)return;const [i,j]=btn.dataset.set.split('-').map(Number),x=d.items[i];if(x.skipped){toast('Убери отметку «Пропустить»');return}x.done[j]=!x.done[j];btn.classList.toggle('is-done',x.done[j]);btn.textContent=x.done[j]?'✓ Сделал':'○ Сделал';btn.setAttribute('aria-pressed',String(x.done[j]));persistWorkoutDraft()});
 body.addEventListener('change',e=>{const el=e.target,k=el.dataset||{};if(k.weight!==undefined){const n=num(el.value);if(n>=0&&n<=600)d.items[+k.weight].weight=n;else{toast('Проверь вес');return}}
 if(k.reps!==undefined){const [i,j]=k.reps.split('-').map(Number);d.items[i].actual[j]=Math.max(0,Math.min(100,Number(el.value)||0))}
 if(k.rir!==undefined)d.items[+k.rir].rir=Number(el.value);
 if(k.pain!==undefined)d.items[+k.pain].pain=el.value==='yes';
 if(k.comment!==undefined)d.items[+k.comment].comment=el.value.slice(0,250);
 if(k.skip!==undefined){const x=d.items[+k.skip];x.skipped=el.checked;if(x.skipped)x.done.fill(false);body.querySelectorAll(`[data-exercise="${k.skip}"] [data-set]`).forEach(b=>{b.classList.remove('is-done');b.textContent='○ Сделал';b.setAttribute('aria-pressed','false')})}
 if(el.id==='wkDate')d.date=el.value;
 if(el.id==='wkEffort')d.effort=el.value;
 if(el.id==='wkSteps')d.steps=el.value.trim()?Math.max(0,Number(el.value)):null;
 persistWorkoutDraft()});
 body.addEventListener('input',e=>{if(e.target.id==='wkFeeling'){d.feeling=e.target.value;save()}});
 $('wkPause').onclick=()=>{save();close();render();toast('Черновик тренировки сохранён — можно продолжить')};
 $('wkFinish').onclick=()=>{d.feeling=$('wkFeeling').value;d.effort=$('wkEffort').value;d.steps=$('wkSteps').value?Number($('wkSteps').value):null;const done=countDone(d);if(!done&&!d.feeling.trim()){toast('Отметь выполненные подходы или запиши причины пропуска');return}if(!confirm(`Завершить тренировку? Выполнено ${done} из ${countPlanned(d)} запланированных подходов. Неотмеченные подходы считаются пропущенными.`))return;
 const items=d.items.map(x=>({id:x.id,name:x.name,weight:x.weight,reps:x.done.map((v,i)=>v?x.actual[i]:null).filter(v=>v!==null).join('/'),setsPlanned:x.sets,setsDone:x.done.filter(Boolean).length,rir:x.rir,pain:x.pain,comment:x.comment||'',skipped:x.skipped||!x.done.some(Boolean)}));
 const workout={id:d.id,date:d.date,items,feeling:d.feeling,effort:d.effort,steps:d.steps,created:d.created,returnPhase:(p.trainingPhase||'return')==='return'};p.workouts.push(workout);p.activeWorkout=null;save();close();render();if(config.url&&config.key){toast('Тренировка сохранена. Анализирую итог один раз…');askWorkoutReview(workout)}else{toast('Тренировка сохранена. Для ИИ-разбора подключи сервер');workoutDetail(workout.id)}}})}
$('startWorkout').onclick=$('quickWorkout').onclick=startWorkout;
function showWorkoutReview(w){let z=w.review;if(!z)return;modal('Оценка тренировки',`<div class="s-note"><b>Итог</b><p>${esc(z.summary)}</p></div><div class="section-row"><h2>По упражнениям</h2></div><div class="list">${(z.adjustments||[]).map(x=>`<div class="item"><div class="itembody"><strong>${esc(x.exercise)}</strong><small>${esc(x.recommendation)}<br>${esc(x.reason)}</small></div></div>`).join('')||'<p class="muted">Нет конкретных изменений по упражнениям.</p>'}</div><div class="s-note"><b>Питание</b><p>${esc(z.nutrition)}</p><b>Шаги</b><p>${esc(z.steps)}</p><b>Когда следующая тренировка</b><p>${esc(z.nextSession||'После восстановления')}</p></div>${(z.warnings||[]).length?`<div class="caution">${z.warnings.map(esc).join('<br>')}</div>`:''}<p class="muted">Советы ИИ — ориентир. Они не заменяют медицинскую оценку, особенно если ранее возникала новая головная боль при усилии.</p>${btn('backWorkout','К тренировке','outline')}`,()=>{$('backWorkout').onclick=()=>workoutDetail(w.id)})}
async function askWorkoutReview(w){if(!config.url||!config.key)return toast('Сначала подключи сервер в Профиль → Подключения');if(busy)return;busy=true;try{let p=person(),recent=p.workouts.filter(x=>x.id!==w.id&&x.date<=w.date).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5),meals=p.meals.filter(x=>x.date<=w.date&&x.date>=shift(w.date,-3)).map(x=>({date:x.date,cal:x.cal,p:x.p,f:x.f,c:x.c,description:x.description}));const res=await api('/api/workout-review',{profile:{weight:p.weight,height:p.height,age:p.age,goal:p.goal,cal:p.cal,protein:p.protein,trainingPhase:p.trainingPhase||'return'},workout:w,history:recent,meals,steps:w.steps??null});w.review=res.review;save();busy=false;showWorkoutReview(w)}catch(e){busy=false;toast('Оценка недоступна: '+e.message)}}

function workoutDetail(id){let w=person().workouts.find(x=>x.id===id);if(!w)return;modal('Тренировка · '+dateLabel(w.date),`<p class="muted">${esc(w.feeling||'Ощущения не указаны')}</p><div class="list">${w.items.map(x=>`<div class="item"><div class="itembody"><strong>${esc(x.name)}</strong><small>${x.pain?'⚠ Был дискомфорт · ':''}Запас: ${x.rir} повторения</small></div><div class="numbers"><b>${measure(x.weight)} кг</b><small>${esc(x.reps)} повт.</small></div></div>`).join('')}</div><div class="s-note">Прогрессировать разумно при устойчивой технике, отсутствии болезненных симптомов и нормальном восстановлении, не по одной тренировке.</div>${btn('askWorkoutReview',w.review?'Показать разбор ИИ':'Оценить с ИИ','outline')}${btn('deleteWorkout','Удалить тренировку','danger')}`,()=>{$('askWorkoutReview').onclick=()=>w.review?showWorkoutReview(w):askWorkoutReview(w);$('deleteWorkout').onclick=()=>{if(!confirm('Удалить запись?'))return;person().workouts=person().workouts.filter(x=>x.id!==id);save();close();render()}})}

function configureService(){modal('Защищённый сервер',`<p class="muted">Для анализа фото и Telegram нужен развернутый Cloudflare Worker. OpenAI API оплачивается отдельно от подписки ChatGPT. Секретные ключи OpenAI и Telegram хранятся только на сервере.</p>${field('Адрес сервера (https://…workers.dev)','serverUrl',config.url||'','url','placeholder="https://ration-api.example.workers.dev"')}${field('Код доступа к серверу','serverKey',config.key||'','password','autocomplete="off"')}<label class="compact muted"><input type="checkbox" id="autoPublish" ${config.autoPost!==false?'checked':''}> Предлагать предварительный просмотр Telegram после сохранения</label><div class="actions">${btn('testServer','Проверить связь','outline')}${btn('saveServer','Сохранить','primary')}</div>`,()=>{$('testServer').onclick=async()=>{let old=config;config={url:$('serverUrl').value.trim(),key:$('serverKey').value.trim(),autoPost:$('autoPublish').checked};try{let result=await api('/api/health',{},true);toast(result.ok?'Сервер подключён':'Сервер ответил')}catch(e){toast('Связь не установлена: '+e.message)}finally{config=old}};$('saveServer').onclick=()=>{let url=$('serverUrl').value.trim(),key=$('serverKey').value.trim();if(url&&!/^https:\/\//i.test(url))return toast('Нужен HTTPS-адрес');config={url,key,autoPost:$('autoPublish').checked};saveConfig();close();render();syncWidget();toast('Настройки сервера сохранены')}})}
$('connectBtn').onclick=configureService;
async function exportBackup(){try{let photos=await allPhotos(),blob=new Blob([JSON.stringify({format:'ration-plus-1',data:db,photos})],{type:'application/json'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='ration-plus-backup-'+dateNow()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('Резервная копия сохранена')}catch(e){toast('Ошибка экспорта: '+e.message)}}
function importBackup(){modal('Импорт резервной копии',`<p class="muted">Восстановит профили, дневник и фото из ранее сохранённого JSON. Текущая история будет заменена.</p><div class="field"><label>Выбрать файл JSON</label><input type="file" accept="application/json,.json" id="backupFile"></div>${btn('backupLoad','Загрузить копию')}`,()=>{$('backupLoad').onclick=async()=>{let f=$('backupFile').files?.[0];if(!f)return toast('Выбери JSON-файл');try{let raw=JSON.parse(await f.text());if(raw.format!=='ration-plus-1'||!Array.isArray(raw.data?.profiles))throw Error('Неверный формат копии');if(!confirm('Заменить все текущие записи данными из копии?'))return;for(const [id,data]of Object.entries(raw.photos||{})){if(typeof data==='string'&&data.startsWith('data:image/'))await storePhoto(id,data)}db=raw.data;save();close();render();toast('История и фото восстановлены')}catch(e){toast('Ошибка импорта: '+e.message)}}})}
$('exportData').onclick=exportBackup;
// Legacy single-line import is kept for old ChatGPT summaries; never silently merge aggregate records.
function acceptLegacy(){let m=location.hash.match(/^#sync=(\d{4}-\d{2}-\d{2})%7C([\d.]+)%7C([\d.]+)$/i)||location.hash.match(/^#sync=(\d{4}-\d{2}-\d{2})\|([\d.]+)\|([\d.]+)$/);if(!m)return;if(confirm('Импортировать суточный итог из предыдущего чата отдельной записью? Не импортирует состав продуктов; возможны дубли.')){let val={id:uid(),name:'Сводка из чата',description:'Суточный итог без детализации',mealType:'Импорт',date:m[1],cal:num(m[2]),p:num(m[3]),f:0,c:0,photoIds:[],source:'Импортировано',created:new Date().toISOString()};person().meals.push(val);save();day=m[1];render()}history.replaceState(null,'',location.pathname+location.search)}
render();acceptLegacy();window.addEventListener('hashchange',acceptLegacy);
if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
})();
